<script>
 import PaintLayer from './PaintLayer.svelte';
 import {onDestroy} from 'svelte';import {layout,resetLayout} from '../layout.svelte';
 import {ChevronLeft,ChevronRight,Maximize,Plus,Minus,Columns2,Grid2X2,Check,X,Expand,Minimize,RotateCcw} from 'lucide-svelte';
 import {studio,asset,change,notify,importImages} from '../studio.svelte';import {clone,initialEdit} from '../api';
 import {previewCache,requestPreview,publishPreview,previewStats} from '../preview-loader';import {sourceKey,previewKey,originalKey,outputGeometry,normalizeEdit} from '../preview-cache';import {createGpuPreview} from '../gpu-preview';
 let stage=$state(),frame=$state(),gpuCanvas=$state(),available=$state({w:800,h:500}),imageSize=$state({w:1600,h:1200});let fit=$derived(Math.min(available.w*.96/imageSize.w,available.h*.96/imageSize.h));
 let selection=$state(null),shown=$state(''),base=$state(''),gpuReady=$state(false),gpuVisible=$state(false),showBusy=$state(false);let drag=null,gpu=null,drawFrame=0,renderToken=0,currentSource='',basis=null,displayed=null,original=null;
 function diagnostics(extra={}){studio.previewDiagnostics={...previewStats(),...(gpu?.stats()||{}),...extra};}
 function keepBasis(entry){if(basis===entry)return;previewCache.retain(entry);previewCache.release(basis);basis=entry;}
 function showExact(entry,signature){if(displayed!==entry){previewCache.retain(entry);previewCache.release(displayed);displayed=entry;}cancelAnimationFrame(drawFrame);shown=entry.url;imageSize={w:entry.width,h:entry.height};gpuVisible=false;if(!studio.draft.strokes?.length){studio.preview=entry.url;studio.previewAssetId=studio.aid;studio.previewSignature=signature;}publishPreview(entry);diagnostics({lastDisplay:'precise'});}
 function paint(entry,edit,a,token){const scheduled=performance.now();cancelAnimationFrame(drawFrame);drawFrame=requestAnimationFrame(()=>{if(token!==renderToken||!gpu||!gpuReady)return;try{if(gpu.draw(entry.bitmap,edit,a.width,a.height)){gpuVisible=true;diagnostics({lastDisplay:'gpu',lastInteractiveMs:performance.now()-scheduled});}}catch{gpuReady=false;gpuVisible=false;studio.previewEngine='cpu';}});}
 const identity=e=>!e.crop&&!e.rotation&&!e.flipH&&!e.flipV&&(e.adjustmentEnabled===false||e.adjustmentOpacity===0||(!e.exposure&&e.contrast===1&&e.saturation===1&&!e.temperature));
 $effect(()=>{const canvas=gpuCanvas,enabled=studio.gpuPreviewEnabled;if(!canvas)return;if(!enabled){gpuReady=false;gpuVisible=false;studio.previewEngine='cpu';return;}const renderer=createGpuPreview(canvas,()=>{gpuReady=false;gpuVisible=false;studio.previewEngine='cpu';});gpu=renderer;gpuReady=!!renderer;studio.previewEngine=renderer?'gpu':'cpu';diagnostics();return()=>{renderer?.dispose();if(gpu===renderer)gpu=null;};});
 $effect(()=>{
  const a=asset(),pid=studio.pid,root=studio.dataRoot,canGpu=gpuReady&&studio.gpuPreviewEnabled;const draft={...clone(studio.draft),strokes:[]},edit=normalizeEdit(studio.tool==='crop'?{...draft,crop:null,rotation:0,flipH:false,flipV:false}:draft);const token=++renderToken;let live=true;const controller=new AbortController();let sourceTimer,preciseTimer,busyTimer;
  if(!a){shown='';gpuVisible=false;return;}
  const source=sourceKey(root,pid,a),basisKey=source+'|basis',key=previewKey(root,pid,a,edit),signature=JSON.stringify(edit),plain=identity(edit);const geometry=outputGeometry(a.width,a.height,edit);imageSize={w:geometry.width,h:geometry.height};
  if(currentSource!==source){currentSource=source;cancelAnimationFrame(drawFrame);gpuVisible=false;shown=studio.thumbs[a.id]||'';previewCache.release(displayed);displayed=null;previewCache.release(basis);basis=null;selection=null;}
  studio.previewBusy=false;showBusy=false;
  const exact=previewCache.get(key)||(plain?previewCache.get(basisKey):null);
  if(exact){showExact(exact,signature);return()=>{live=false;controller.abort();};}
  const cachedBasis=previewCache.get(basisKey);if(cachedBasis){keepBasis(cachedBasis);if(canGpu)paint(cachedBasis,edit,a,token);}
  function fail(e){if(live&&e.name!=='AbortError'&&!e.message.includes('PREVIEW_SUPERSEDED'))studio.error=e.message;}
  function settled(){if(live){studio.previewBusy=false;showBusy=false;clearTimeout(busyTimer);}}
  const refine=()=>{if(!live)return;studio.previewBusy=true;busyTimer=setTimeout(()=>{if(live)showBusy=true;},250);requestPreview(key,'preview',{projectId:pid,assetId:a.id,edit},{priority:1,signal:controller.signal}).then(entry=>{if(live&&token===renderToken)showExact(entry,signature);}).catch(fail).finally(settled);};
  if((canGpu||plain)&&!cachedBasis){sourceTimer=setTimeout(()=>{if(!live)return;studio.previewBusy=true;if(plain)busyTimer=setTimeout(()=>{if(live)showBusy=true;},250);requestPreview(basisKey,'preview_source',{projectId:pid,assetId:a.id},{priority:0,signal:controller.signal}).then(entry=>{if(!live||token!==renderToken)return;keepBasis(entry);if(plain){showExact(entry,signature);settled();}else if(canGpu)paint(entry,edit,a,token);}).catch(e=>{if(live&&e.name!=='AbortError'){if(plain)refine();else fail(e);}});},45);}
  if(!plain)preciseTimer=setTimeout(refine,canGpu?220:85);
  return()=>{live=false;controller.abort();clearTimeout(sourceTimer);clearTimeout(preciseTimer);clearTimeout(busyTimer);cancelAnimationFrame(drawFrame);};
 });
 $effect(()=>{const a=asset(),pid=studio.pid,root=studio.dataRoot,compare=studio.compare;const controller=new AbortController();let live=true;base='';previewCache.release(original);original=null;if(!a||!compare)return;const key=originalKey(root,pid,a);const display=entry=>{if(!live)return;previewCache.retain(entry);original=entry;base=entry.url;studio.original=entry.url;diagnostics();};const cached=previewCache.get(key);if(cached)display(cached);else requestPreview(key,'original_preview',{projectId:pid,assetId:a.id},{priority:2,signal:controller.signal}).then(display).catch(e=>{if(live&&e.name!=='AbortError')studio.error=e.message;});return()=>{live=false;controller.abort();};});
 $effect(()=>{if(!stage)return;let measured=false;const observer=new ResizeObserver(()=>{const next={w:stage.clientWidth,h:stage.clientHeight};const oldFit=Math.min(available.w*.96/imageSize.w,available.h*.96/imageSize.h),newFit=Math.min(next.w*.96/imageSize.w,next.h*.96/imageSize.h);if(measured&&!studio.canvasFit&&oldFit>0&&newFit>0)studio.zoom=studio.zoom*oldFit/newFit;available=next;measured=true;});observer.observe(stage);return()=>observer.disconnect();});
 onDestroy(()=>{cancelAnimationFrame(drawFrame);previewCache.release(basis);previewCache.release(displayed);previewCache.release(original);});
 function resetView(e){if(studio.paintTool&&!studio.spacePan)return;if(e&&e.button!==0)return;if(e?.target?.closest('button,select,textarea'))return;drag=null;studio.zoom=1;studio.canvasFit=true;studio.pan={x:0,y:0};}
 function point(e){const r=frame.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];}
 function down(e){if(e.button!==0||studio.compare||studio.paintMenuOpen||studio.busy||(studio.paintTool&&!studio.spacePan&&studio.tool!=='crop'))return;e.currentTarget.closest('.canvas-stage')?.focus({preventScroll:true});if(studio.tool==='crop')drag={start:point(e)};else drag={x:e.clientX,y:e.clientY,pan:{...studio.pan}};e.currentTarget.setPointerCapture(e.pointerId);}
 function move(e){if(!drag)return;if(drag.start){const p=point(e),r=frame.getBoundingClientRect();if(Math.hypot((p[0]-drag.start[0])*r.width,(p[1]-drag.start[1])*r.height)<3)return;selection=[Math.min(p[0],drag.start[0]),Math.min(p[1],drag.start[1]),Math.abs(p[0]-drag.start[0]),Math.abs(p[1]-drag.start[1])];}else studio.pan={x:drag.pan.x+e.clientX-drag.x,y:drag.pan.y+e.clientY-drag.y};}
 $effect(()=>{if(studio.tool!=='crop')selection=null;});
 function applyCrop(){if(selection&&selection[2]>.005&&selection[3]>.005){change({crop:selection});selection=null;studio.tool='adjust';notify("已应用裁切");}}
 function key(e){if(e.defaultPrevented||studio.paintMenuOpen)return;if(e.key==='Enter'&&studio.tool==='crop')applyCrop();if(e.key==='Escape')selection=null;}
</script>
<svelte:window onkeydown={key}/>
<div class="canvas-top"><div class="canvas-file"><b>{asset()?.name||"尚未选择图片"}</b><span>{asset()?`${asset().width} × ${asset().height}`:''}</span></div><div class="canvas-top-actions"><button class="focus-canvas" class:active={layout.focus} aria-label={layout.focus?"显示面板":"专注编辑"} aria-pressed={layout.focus} title={layout.focus?"显示面板":"专注编辑"} onclick={()=>layout.focus=!layout.focus}>{#if layout.focus}<Minimize size={14}/>{:else}<Expand size={14}/>{/if}<span>专注编辑</span></button><button class="reset-layout" aria-label="恢复默认布局" title="恢复默认布局" onclick={resetLayout}><RotateCcw size={13}/></button><div class="segmented"><button class:active={studio.view==='canvas'} onclick={()=>studio.view='canvas'}>画布</button><button onclick={()=>studio.view='grid'}><Grid2X2 size={13}/>图片列表</button></div></div></div>
<!-- svelte-ignore a11y_no_noninteractive_element_interactions (Double-click duplicates the accessible Fit image action.) -->
<div ondblclick={resetView} bind:this={stage} class={`canvas-stage ${studio.background}`} role="region" aria-label="图片画布" tabindex="-1" data-preview-engine={studio.previewEngine} data-preview-metrics={JSON.stringify(studio.previewDiagnostics)} onwheel={e=>{if(e.ctrlKey){e.preventDefault();studio.canvasFit=false;studio.zoom=Math.max(.2,Math.min(5,studio.zoom-e.deltaY*.001));}}}>
 {#if asset()}<div bind:this={frame} class:crop-cursor={studio.tool==='crop'} class="photo-wrap" style:width={`${imageSize.w*fit}px`} style:height={`${imageSize.h*fit}px`} style:transform={`translate(${studio.pan.x}px,${studio.pan.y}px) scale(${studio.zoom})`} role="img" aria-label="正在编辑的图片" onpointerdown={down} onpointermove={move} onpointerup={()=>drag=null} onpointercancel={()=>drag=null} onlostpointercapture={()=>drag=null}>
 <img class:under-gpu={gpuVisible} src={shown||studio.thumbs[studio.aid]} alt={asset().name} draggable="false"/>
 <canvas bind:this={gpuCanvas} class="gpu-preview" class:active={gpuVisible} aria-hidden="true"></canvas>
 <PaintLayer/>
 {#if studio.compare}<div class="compare-before" style:clip-path={`inset(0 ${100-studio.split}% 0 0)`}>{#if base}<img src={base} alt="原图" draggable="false"/>{:else}<span class="original-loading">正在加载原图</span>{/if}</div><div class="compare-line" style:left={`${studio.split}%`}><span><ChevronLeft size={11}/><ChevronRight size={11}/></span></div><input class="compare-slider" type="range" min="0" max="100" bind:value={studio.split} aria-label="拖动对比原图"/><span class="compare-label before">原图</span><span class="compare-label after">编辑后</span>{/if}
 {#if selection}<div class="crop-rectangle" style:left={`${selection[0]*100}%`} style:top={`${selection[1]*100}%`} style:width={`${selection[2]*100}%`} style:height={`${selection[3]*100}%`}><i></i><i></i></div>{/if}
 </div>{:else}<div class="empty"><h2>尚未选择图片</h2><span>导入图片，或将文件夹拖入项目。</span><div class="button-row"><button class="primary" onclick={()=>importImages(false)}>导入图片</button><button class="line-button" onclick={()=>importImages(true)}>导入文件夹</button></div></div>{/if}
 {#if showBusy}<span class="render-badge" role="status">{gpuVisible?"正在生成清晰预览":"正在加载预览"}</span>{/if}
 {#if selection}<div class="crop-confirm"><button onclick={()=>selection=null}><X size={14}/>取消</button><button class="primary" onclick={applyCrop}><Check size={14}/>应用裁切</button></div>{/if}
</div>
<div class="canvas-bottom"><div class="canvas-bottom-left">{#if asset()&&!studio.paintTool}<button onclick={()=>{studio.paintTool='brush';studio.tool='adjust';studio.brush={color:'#e32a32',size:3,hardness:1,opacity:1};}} aria-label="精准标注画笔">标注画笔</button>{/if}{#if studio.paintTool}<span class="paint-tool-status"><i style:background={studio.brush.color}></i>{studio.picking?"点击图片取色，按 Esc 取消":`${studio.paintTool==='brush'?"画笔":"橡皮擦"} · ${studio.paintTool==='brush'?studio.brush.size:studio.eraser.size}px`}<input aria-label="标注颜色" type="color" bind:value={studio.brush.color} style="width:24px;height:22px;padding:0"/><input aria-label="标注笔宽" type="number" min="1" max="500" value={studio.brush.size} onchange={e=>{const value=Number(e.currentTarget.value);studio.brush.size=Number.isFinite(value)?Math.min(500,Math.max(1,value)):3;}} style="width:54px;height:24px;padding:2px 4px"/><button onclick={()=>{studio.paintTool=null;studio.picking=false;}}>完成</button></span>{/if}<button class:active={studio.compare} onclick={()=>studio.compare=!studio.compare} disabled={!asset()}><Columns2 size={15}/>对比原图</button><button class="background-button" aria-label="更改画布背景" onclick={()=>studio.background=studio.background==='paper'?'checker':studio.background==='checker'?'dark':'paper'}><span class={`swatch ${studio.background}`}></span></button>{#if studio.tool==='crop'}<span class="hint">拖动选择裁切范围，按回车键应用</span>{/if}</div><div class="zoom-controls"><button onclick={()=>{studio.canvasFit=false;studio.zoom=Math.max(.2,studio.zoom-.1);}} aria-label="缩小"><Minus size={13}/></button><button onclick={()=>{studio.zoom=1;studio.canvasFit=true;studio.pan={x:0,y:0};}}>{Math.round(studio.zoom*100)}%</button><button onclick={()=>{studio.canvasFit=false;studio.zoom=Math.min(5,studio.zoom+.1);}} aria-label="放大"><Plus size={13}/></button><button onclick={()=>{studio.zoom=1;studio.canvasFit=true;studio.pan={x:0,y:0};}} aria-label="适配并居中"><Maximize size={13}/></button></div></div>



